const body = $('Fetch Due').first().json;
const initial = body.initial || [];
const followup = body.followup || [];
const dayahead = body.dayahead || [];
const total = initial.length + followup.length + dayahead.length;
if (!total) return [];
const line = (x) => `<tr><td style="padding:4px 10px 4px 0;color:#6b7280;font:13px -apple-system,sans-serif">${x.artist_name}</td><td style="padding:4px 0;font:13px -apple-system,sans-serif">${x.venue}${x.show_date ? ' — ' + x.show_date : ''}</td></tr>`;
let html = '<div style="font-family:-apple-system,sans-serif">';
if (initial.length) {
  html += `<p><b>${initial.length} welcome email${initial.length===1?'':'s'} sent</b></p><table>${initial.map(line).join('')}</table>`;
}
if (followup.length) {
  html += `<p style="margin-top:14px"><b>${followup.length} follow-up${followup.length===1?'':'s'} sent</b></p><table>${followup.map(line).join('')}</table>`;
}
if (dayahead.length) {
  html += `<p style="margin-top:14px"><b>${dayahead.length} day-before confirmation${dayahead.length===1?'':'s'} sent</b></p><table>${dayahead.map(line).join('')}</table>`;
}
html += '<p style="margin-top:14px">Sent via Outlook — nothing to review, this is just a summary.</p></div>';
const parts = [];
if (initial.length) parts.push(`${initial.length} welcome`);
if (followup.length) parts.push(`${followup.length} follow-up`);
if (dayahead.length) parts.push(`${dayahead.length} day-before`);
const subject = `Advance update — ${parts.join(', ')}`;
return [{ json: { subject, html } }];

const EXPECTED_TOKEN = 'REPLACE_WITH_ADVANCE_INTERNAL_TOKEN';
const headers = $input.first().json.headers || {};
const token = headers['x-advance-token'];
if (token !== EXPECTED_TOKEN) {
  return [];
}
return [{ json: {} }];
